const person = id => PEOPLE.find(p => p.id === id);
const initials = n => n.split(" ").slice(-2).map(w => w[0]).join("").toUpperCase();
const fmtDate = d => new Date(d + "T00:00:00").toLocaleDateString("vi-VN", {day:"2-digit", month:"2-digit", year:"numeric"});
const driveDl = id => "https://drive.google.com/uc?export=download&id=" + id;
function toast(msg){
  const t = document.createElement("div"); t.className = "toast";
  t.innerHTML = '<span class="dot">' + I("checkmark") + '</span>' + esc(msg);
  $("#toasts").appendChild(t); setTimeout(() => t.remove(), 2400);
}
async function copy(text, label){
  try { await navigator.clipboard.writeText(text); }
  catch(e){ const ta=document.createElement("textarea"); ta.value=text; document.body.appendChild(ta); ta.select(); try{document.execCommand("copy")}catch(_){} ta.remove(); }
  toast("Đã copy " + (label || text));
}

/* ---------- Navigation ---------- */
function go(tab){
  $$(".tab").forEach(t => t.setAttribute("aria-selected", t.dataset.tab === tab));
  $$(".view").forEach(v => v.classList.toggle("active", v.id === "view-" + tab));
  window.scrollTo({top:0, behavior:"smooth"});
}
function setSub(sub){
  $$("[data-sub]").forEach(x => x.setAttribute("aria-pressed", x.dataset.sub === sub));
  $$(".subpanel").forEach(x => x.hidden = x.id !== "sub-" + sub);
}
document.addEventListener("click", e => {
  const g = e.target.closest("[data-go]"); if (g){ e.preventDefault(); go(g.dataset.go); }
  const gs = e.target.closest("[data-go-sub]"); if (gs){ go("brand"); setSub(gs.dataset.goSub); }
  const t = e.target.closest(".tab"); if (t) go(t.dataset.tab);
  const s = e.target.closest("[data-sub]"); if (s) setSub(s.dataset.sub);
  if (e.target.closest("[data-open=contribute]")) openModal();
  if (e.target.closest("[data-open=font-upload]")) openFontModal();
  if (e.target.closest("[data-close]") || e.target === $("#scrim")) closeAll();
  const sw = e.target.closest(".sw"); if (sw) copy(sw.dataset.hex, sw.dataset.name + " " + sw.dataset.hex);
  const fo = e.target.closest("[data-font-open]"); if (fo) openFont(fo.dataset.fontOpen);
  const pc = e.target.closest("[data-proj]"); if (pc) openProject(+pc.dataset.proj);
  const ty = e.target.closest("[data-type]"); if (ty){ fType = ty.dataset.type; $$("[data-type]").forEach(x => x.setAttribute("aria-pressed", x === ty)); renderProjects(); }
  const fc = e.target.closest("[data-fcat]"); if (fc){ fCat = fc.dataset.fcat; $$("[data-fcat]").forEach(x => x.setAttribute("aria-pressed", x === fc)); renderFonts(); }
  const ac = e.target.closest("[data-act]"); if (ac) toast(ac.dataset.act);
});
