function fontFiles(f){
  if (f.src === "upload" || f.src === "cloud") return f.files;
  return (f.files || []).map(key => {
    const w = FONT_FILES[key].w;
    const label = (key === "bricolage" || key === "phudu") ? "Variable" : w.includes(" ") ? f.weights[0][1] : (WN[w] || "Regular");
    return { label, href: FONT_FILES[key].uri, name: `${f.name} ${label}.woff2` };
  });
}
function downloadFont(f, idx=0){
  if (f.src === "ds"){ window.open(f.url, "_blank", "noopener"); return; }
  const files = fontFiles(f); const file = files[idx]; if (!file) return;
  saveUrl(file.href, file.name);
}
async function saveUrl(href, name){
  toast("Đang tải " + name);
  if (/^https?:/.test(href) && !href.startsWith(location.origin)){
    try { const b = await (await fetch(href)).blob(); saveBlob(b, name); return; } catch(e){ window.open(href, "_blank", "noopener"); return; }
  }
  const a = document.createElement("a"); a.href = href; a.download = name; document.body.appendChild(a); a.click(); a.remove();
}
