/* ---------- Font upload: đọc metadata, báo trùng, tự phân loại ---------- */
async function sfntTables(buf){
  const dv = new DataView(buf); const sig = dv.getUint32(0); const tables = {};
  if (sig === 0x774F4646){ // WOFF: bảng nén zlib
    const n = dv.getUint16(12);
    for (let i=0;i<n;i++){
      const o = 44 + 20*i, tag = String.fromCharCode(dv.getUint8(o),dv.getUint8(o+1),dv.getUint8(o+2),dv.getUint8(o+3));
      if (!["name","OS/2","post","head","cmap"].includes(tag)) continue;
      const off = dv.getUint32(o+4), comp = dv.getUint32(o+8), orig = dv.getUint32(o+12);
      let data = buf.slice(off, off+comp);
      if (comp < orig && "DecompressionStream" in window){ data = await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream("deflate"))).arrayBuffer(); }
      tables[tag] = new DataView(data);
    }
    return tables;
  }
  if (sig === 0x774F4632) return null; // WOFF2: nén brotli, dùng cách đo bằng canvas
  const n = dv.getUint16(4);
  for (let i=0;i<n;i++){ const o = 12+16*i; const tag = String.fromCharCode(dv.getUint8(o),dv.getUint8(o+1),dv.getUint8(o+2),dv.getUint8(o+3)); const off = dv.getUint32(o+8), len = dv.getUint32(o+12); tables[tag] = new DataView(buf, off, len); }
  return tables;
}
async function parseFontMeta(buf){
  try{
    const t = await sfntTables(buf); if (!t) return {};
    const out = {};
    if (t["OS/2"]){ const o = t["OS/2"]; out.weight = o.getUint16(4); out.avgW = o.getInt16(2); out.famClass = o.getInt16(30) >> 8; out.panose = Array.from({length:10}, (_,i) => o.getUint8(32+i)); }
    if (t.head) out.upm = t.head.getUint16(18);
    if (t.post) out.mono = t.post.getUint32(12) !== 0;
    if (t.name){
      const v = t.name, count = v.getUint16(2), so = v.getUint16(4); const names = {};
      for (let i=0;i<count;i++){
        const r = 6+12*i, pid = v.getUint16(r), nid = v.getUint16(r+6), len = v.getUint16(r+8), off = v.getUint16(r+10);
        if (![1,2,4,16,17].includes(nid) || names[nid+"_"+pid]) continue;
        let s = ""; if (pid === 3 || pid === 0){ for (let j=0;j<len;j+=2) s += String.fromCharCode(v.getUint16(so+off+j)); } else { for (let j=0;j<len;j++) s += String.fromCharCode(v.getUint8(so+off+j)); }
        names[nid+"_"+pid] = s;
      }
      const pick = id => names[id+"_3"] || names[id+"_0"] || names[id+"_1"];
      out.family = pick(16) || pick(1); out.style = pick(17) || pick(2);
    }
    return out;
  }catch(e){ return {}; }
}
// đo bằng canvas khi không đọc được bảng (WOFF2) và để kiểm tra dấu tiếng Việt
function measureFont(fam){
  const c = document.createElement("canvas").getContext("2d");
  const w = (txt, f) => { c.font = `100px ${f}`; return c.measureText(txt).width; };
  const F = `'${fam}'`;
  const mono = Math.abs(w("iiiiiiiiii", F) - w("MMMMMMMMMM", F)) < 2;
  const ratio = w("abcdefghijklmnopqrstuvwxyz", F) / 26 / 100; // bề rộng trung bình / cỡ chữ
  const vn = ["ặ","ễ","ợ","ữ","ỷ","đ","Ơ"].every(ch => Math.abs(w(ch, `${F}, monospace`) - w(ch, `${F}, serif`)) < 0.5);
  return {mono, ratio, vn};
}
const USE_BY_CAT = {"Sans":"Body, tiêu đề, UI.","Grotesk":"Headline hiện đại, poster.","Rounded":"Nội dung thân thiện, trẻ em, sticker.","Serif":"Editorial, ấn phẩm cao cấp.","Condensed":"Giá sale, headline dài, banner nhiều chữ.","Display":"Key visual, headline sự kiện.","Tech":"Công nghệ, gaming.","Retro":"Chủ đề hoài niệm, lễ hội truyền thống.","Script":"Lễ, Tết, thiệp chúc mừng.","Brush":"Sale sốc, thể thao, năng động.","Viết tay":"Ghi chú, lời nhắn, nội dung trẻ.","Vui nhộn":"Thiếu nhi, social vui.","Thư pháp":"Tết, chủ đề truyền thống.","Mono":"Bảng thông số, số liệu, code."};
function classifyFont(meta, name, m){
  const n = (name || "").toLowerCase();
  const kw = [[/mono|code/,"Mono"],[/brush|graffiti/,"Brush"],[/hand|viet tay|marker|chalk|crayon/,"Viết tay"],[/script|signature|calligraph/,"Script"],[/thu phap|dinh tran/,"Thư pháp"],[/round|rnd/,"Rounded"],[/grotesk|grotesque/,"Grotesk"],[/condensed|compressed|narrow|bebas|anton|cond/,"Condensed"],[/didot|serif|georgia|garamond|times|bodoni/,"Serif"],[/slab|retro|vintage/,"Retro"],[/tech|euro|digital|cyber/,"Tech"]];
  for (const [re,c] of kw) if (re.test(n) && !(c === "Serif" && /sans/.test(n))) return {cat:c, why:"theo tên font"};
  if (meta.mono || m.mono || meta.panose?.[3] === 9) return {cat:"Mono", why:"chữ đều độ rộng"};
  const p = meta.panose || [];
  if (p[0] === 3 || meta.famClass === 10) return {cat:"Script", why:"metadata: chữ viết tay / script"};
  if (p[0] === 4 || meta.famClass === 9) return {cat:"Display", why:"metadata: font trang trí"};
  if ((meta.famClass >= 1 && meta.famClass <= 7) || (p[0] === 2 && p[1] >= 2 && p[1] <= 10)) return {cat:"Serif", why:"metadata: có chân"};
  if (p[1] === 15) return {cat:"Rounded", why:"metadata: nét bo tròn"};
  const ratio = meta.avgW && meta.upm ? meta.avgW / meta.upm : m.ratio;
  if (ratio && ratio < 0.43) return {cat:"Condensed", why:"đo được: chữ hẹp"};
  if ((meta.weight || 400) >= 800) return {cat:"Display", why:"weight rất đậm"};
  return {cat:"Sans", why: meta.panose ? "metadata: không chân" : "mặc định"};
}
const norm = s => (s || "").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^a-z0-9]/g,"");
const KNOWN_HASH = new Set();
async function sha1(buf){ const h = await crypto.subtle.digest("SHA-1", buf); return Array.from(new Uint8Array(h)).map(b => b.toString(16).padStart(2,"0")).join(""); }
function findDup(p){
  if (KNOWN_HASH.has(p.hash)) return "file giống hệt đã có";
  const key = norm(p.name), st = norm(p.style);
  const f = FONTS.find(x => norm(x.name) === key || norm(x.name).replace(/^svn|^1ftvvip|^dfvn|^ps|^utm|^nvn/,"") === key.replace(/^svn|^1ftvvip|^dfvn|^ps|^utm|^nvn/,""));
  if (f){
    const ws = f.weights.map(w => norm(w[1]));
    if (!st || ws.includes(st) || f.weights.some(w => w[0] === p.weight)) return `đã có “${f.name}”` + (p.style ? ` (${p.style})` : "");
    return `bổ sung weight cho “${f.name}”`;
  }
  return null;
}
let pending = [];
const UP_CATS = FONT_CATS.filter(c => !["Tất cả","Design System","Team tải lên"].includes(c));
function fdropDefault(){ $("#fdrop-inner").innerHTML = I("upload").replace('class="i"','class="i" style="font-size:28px;margin:0 auto 6px;color:var(--primary-500)"') + '<b>Kéo thả nhiều file font vào đây</b><div style="font-size:12px;margin-top:4px">TTF, OTF, WOFF, WOFF2 · chọn cả thư mục font cũng được</div>'; }
function openFontModal(){
  if (!requireAuth("tải font lên")) return;
  lastFocus = document.activeElement; pending.forEach(p => URL.revokeObjectURL(p.href)); pending = [];
  $("#fform").reset(); $("#up-list").innerHTML = ""; $("#fsubmit").disabled = true; fdropDefault();
  $("#fmodal").classList.add("open"); $("#fmodal").setAttribute("aria-hidden","false"); $("#scrim").classList.add("open");
}
async function addPending(files){
  for (const file of files){
    if (!/\.(ttf|otf|woff2?)$/i.test(file.name)){ continue; }
    const buf = await file.arrayBuffer(); const hash = await sha1(buf);
    if (pending.some(p => p.hash === hash)) continue;
    const meta = await parseFontMeta(buf);
    const id = "u" + Date.now().toString(36) + Math.random().toString(36).slice(2,6);
    const fam = "U_" + id;
    try { const ff = new FontFace(fam, buf, {weight:"1 1000"}); await ff.load(); document.fonts.add(ff); }
    catch(e){ toast("Không đọc được " + file.name); continue; }
    const base = file.name.replace(/\.(ttf|otf|woff2?)$/i,"").replace(/[-_]+/g," ");
    const name = (meta.family || base.replace(/\s+(thin|light|regular|book|medium|semibold|bold|extrabold|black|heavy|italic)\b.*$/i,"")).trim();
    const weight = meta.weight && meta.weight >= 100 && meta.weight <= 900 ? Math.round(meta.weight/100)*100 : (/black|heavy/i.test(base)?900:/extrabold/i.test(base)?800:/bold/i.test(base)?700:/semibold/i.test(base)?600:/medium/i.test(base)?500:/light/i.test(base)?300:/thin/i.test(base)?100:400);
    const m = measureFont(fam);
    const cls = classifyFont(meta, name + " " + base, m);
    const p = {id, fam, buf, hash, file, name, style: meta.style || WN[weight], weight, cat: cls.cat, why: cls.why, vn: m.vn, href: URL.createObjectURL(file), fileName: file.name, size: file.size};
    p.dup = findDup(p); p.include = !p.dup || p.dup.startsWith("bổ sung");
    pending.push(p);
  }
  renderPending();
}
function renderPending(){
  const dups = pending.filter(p => !p.include).length;
  $("#up-list").innerHTML = (pending.length ? `<div class="up-sum"><span class="tag">${pending.length} file</span>${dups ? `<span class="tag amber">${dups} font đã có, đã bỏ chọn</span>` : '<span class="tag green">Không có font trùng</span>'}</div>` : "") +
    pending.map((p,i) => `
    <div class="up-item${p.dup && !p.dup.startsWith("bổ sung") ? ' dup' : ''}">
      <input type="checkbox" class="chk" data-pi="${i}" data-pf="include" ${p.include ? 'checked' : ''} aria-label="Thêm font này">
      <div class="pv" style="font-family:'${p.fam}'">Aa</div>
      <div class="nm">
        <input type="text" value="${esc(p.name)}" data-pi="${i}" data-pf="name" aria-label="Tên font">
        <div class="row2"><select data-pi="${i}" data-pf="cat" aria-label="Nhóm font" style="flex:1">${UP_CATS.map(c => `<option ${c===p.cat?'selected':''}>${c}</option>`).join("")}</select>
          ${p.vn ? '<span class="tag green">Đủ dấu tiếng Việt</span>' : '<span class="tag amber">Thiếu dấu tiếng Việt</span>'}</div>
        <small>${esc(p.fileName)} · ${esc(p.style)} · ${(p.size/1024).toFixed(0)} KB · tự nhận: ${esc(p.cat)} (${esc(p.why)})${p.dup ? ` · <b style="color:var(--warning-800)">${esc(p.dup)}</b>` : ''}</small>
      </div>
      <button type="button" class="icon-btn" data-prm="${i}" aria-label="Bỏ file này">${I("dismiss")}</button>
    </div>`).join("");
  $("#fsubmit").disabled = !pending.some(p => p.include);
}
$("#f-fonts").addEventListener("change", e => { addPending([...e.target.files]); e.target.value = ""; });
["dragenter","dragover"].forEach(ev => $("#fdrop").addEventListener(ev, () => $("#fdrop").classList.add("over")));
["dragleave","drop"].forEach(ev => $("#fdrop").addEventListener(ev, () => $("#fdrop").classList.remove("over")));
$("#up-list").addEventListener("input", e => { const t = e.target.closest("[data-pi]"); if (!t) return; const p = pending[+t.dataset.pi]; if (t.dataset.pf === "include"){ p.include = t.checked; $("#fsubmit").disabled = !pending.some(x => x.include); } else p[t.dataset.pf] = t.value; });
$("#up-list").addEventListener("change", e => { const t = e.target.closest("select[data-pi]"); if (t) pending[+t.dataset.pi].cat = t.value; });
$("#up-list").addEventListener("click", e => { const r = e.target.closest("[data-prm]"); if (r){ URL.revokeObjectURL(pending[+r.dataset.prm].href); pending.splice(+r.dataset.prm,1); renderPending(); } });
$("#fform").addEventListener("submit", async e => {
  e.preventDefault();
  const sel = pending.filter(p => p.include); if (!sel.length) return;
  const custom = $("#f-use").value.trim();
  const groups = {};
  sel.forEach(p => { const key = norm(p.name); (groups[key] = groups[key] || []).push(p); });
  if (Cloud.on){
    const btn = $("#fsubmit"); btn.classList.add("busy"); btn.lastChild.textContent = "Đang tải lên…";
    const gs = Object.values(groups).map(ps => { const main = ps.find(p => p.weight === 400) || ps[0]; return { name: main.name, cat: main.cat, vn: main.vn, use: custom || USE_BY_CAT[main.cat] || "", files: ps.map(p => ({ file: p.file, weight: p.weight, style: p.style, hash: p.hash })) }; });
    try {
      const r = await Cloud.saveFonts(gs);
      await loadCloud(); fCat = "Team tải lên"; renderFonts(); closeAll(); go("fonts");
      toast(`Đã lưu ${r.added} font mới` + (r.extended ? `, bổ sung ${r.extended} font` : "") + (r.skipped ? ` · ${r.skipped} file đã có` : "") + (r.errors.length ? ` · lỗi: ${r.errors[0]}` : ""));
    } catch(err){ toast("Không lưu được: " + err.message); }
    finally { btn.classList.remove("busy"); btn.lastChild.textContent = "Thêm vào thư viện"; pending = []; }
    return;
  }
  let added = 0, extended = 0;
  Object.values(groups).forEach(ps => {
    ps.sort((a,b) => a.weight - b.weight);
    const existing = FONTS.find(x => norm(x.name) === norm(ps[0].name));
    if (existing && existing.src === "upload"){
      ps.forEach(p => { if (!existing.weights.some(w => w[0] === p.weight)){ existing.weights.push([p.weight, p.style]); existing.files.push({label:p.style, href:p.href, name:p.fileName}); new FontFace(existing.fam, p.buf, {weight:String(p.weight)}).load().then(f => document.fonts.add(f)); } KNOWN_HASH.add(p.hash); });
      existing.weights.sort((a,b) => a[0]-b[0]); extended++; return;
    }
    const main = ps.find(p => p.weight === 400) || ps[0];
    const gfam = "UG_" + main.id;
    ps.forEach(p => { const ff = new FontFace(gfam, p.buf, {weight: ps.length === 1 ? "1 1000" : String(p.weight)}); ff.load().then(f => document.fonts.add(f)); KNOWN_HASH.add(p.hash); });
    const clash = FONTS.some(x => norm(x.name) === norm(main.name));
    FONTS.unshift({ k: main.id, name: main.name.trim() + (clash ? " (bổ sung)" : ""), fam: gfam, cat: main.cat, src: "upload", role: "Tải lên bởi Bạn" + (main.vn ? "" : " · thiếu dấu TV"), weights: ps.map(p => [p.weight, p.style]), use: custom || USE_BY_CAT[main.cat] || "Font do team tải lên.", lic: "check",
      files: ps.map(p => ({ label: p.style, href: p.href, name: p.fileName })) });
    added++;
  });
  const skipped = pending.length - sel.length; pending = [];
  fCat = "Team tải lên"; renderFonts(); counts(); closeAll(); go("fonts");
  toast(`Đã thêm ${added} font mới` + (extended ? `, bổ sung weight cho ${extended} font` : "") + (skipped ? ` · bỏ qua ${skipped} file đã có` : ""));
});

