/* Logo drawer: chọn nền, size, định dạng */
let LD = {};
function openLogo(k){
  const t = LOGO_TYPES.find(x => x.k === k);
  const sizes = t.sizes || LOGO_SIZES;
  LD = {t, bg: "l", size: sizes[0][1], fmt: "svg"};
  $("#drawer-title").textContent = "Tải logo";
  $("#drawer-body").innerHTML = `
    <h3 class="title" style="margin-bottom:4px">${t.name}</h3>
    <p style="margin:0 0 16px;color:var(--gray-600);font-size:13px">${t.sub}</p>
    <div class="ld-stage l" id="ld-stage"></div>
    ${t.light !== t.dark ? `<div class="opt-row"><b>Nền</b><div class="seg" id="ld-bg"><button type="button" data-v="l" aria-pressed="true">Nền sáng</button><button type="button" data-v="d" aria-pressed="false">Nền tối</button></div></div>` : ''}
    <div class="opt-row"><b>Size</b><div class="chips" id="ld-size">${sizes.map(([n,h],i) => `<button type="button" class="chip" data-v="${h}" aria-pressed="${i===0}">${n}${t.square ? '' : ' · '+h+'px'}</button>`).join("")}</div>
      <label class="custom-h">Tuỳ chỉnh <input type="number" id="ld-custom" min="12" max="2000" placeholder="${t.square?'px':'cao px'}"></label></div>
    <div class="opt-row"><b>Định dạng</b><div class="seg" id="ld-fmt"><button type="button" data-v="svg" aria-pressed="true">SVG</button><button type="button" data-v="png1" aria-pressed="false">PNG @1x</button><button type="button" data-v="png2" aria-pressed="false">PNG @2x</button><button type="button" data-v="png3" aria-pressed="false">PNG @3x</button></div></div>
    <div class="dl-summary" id="ld-sum"></div>
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      <button class="btn btn-primary" id="ld-go">${I("download")}Tải logo</button>
      <button class="btn btn-ghost" id="ld-all">${I("folder")}Tải trọn bộ SVG</button>
      <button class="btn btn-ghost" id="ld-copy">${I("copy")}Copy SVG</button>
      <a class="btn btn-ghost" href="${DS+t.node}" target="_blank" rel="noopener">${I("external")}Figma</a>
    </div>`;
  const upd = () => {
    const key = LD.bg === "d" ? t.dark : t.light;
    const ratio = t.w / t.h;
    const w = Math.round(LD.size * ratio), h = LD.size;
    const scale = {svg:1, png1:1, png2:2, png3:3}[LD.fmt];
    const show = Math.min(h, t.square ? 200 : 120);
    $("#ld-stage").className = "ld-stage " + (LD.bg === "d" ? "d" : "l");
    $("#ld-stage").innerHTML = svgSized(key, show, ratio);
    $("#ld-sum").textContent = `${w} × ${h}px` + (LD.fmt === "svg" ? " · SVG vector, phóng to không vỡ" : ` · xuất ${w*scale} × ${h*scale}px (PNG nền trong)`);
  };
  const bind = (id, fn) => { const g = $(id); if (!g) return; g.addEventListener("click", e => { const b = e.target.closest("[data-v]"); if (!b) return; g.querySelectorAll("[data-v]").forEach(x => x.setAttribute("aria-pressed", x === b)); fn(b.dataset.v); upd(); }); };
  bind("#ld-bg", v => LD.bg = v);
  bind("#ld-size", v => { LD.size = +v; $("#ld-custom").value = ""; });
  bind("#ld-fmt", v => LD.fmt = v);
  $("#ld-custom").addEventListener("input", e => { const v = +e.target.value; if (v >= 12){ LD.size = v; $$("#ld-size [data-v]").forEach(x => x.setAttribute("aria-pressed", false)); upd(); } });
  $("#ld-go").addEventListener("click", () => downloadLogo(t, LD.bg, LD.size, LD.fmt));
  $("#ld-copy").addEventListener("click", () => copy(svgSized(LD.bg === "d" ? t.dark : t.light, LD.size, t.w/t.h), "mã SVG"));
  $("#ld-all").addEventListener("click", async () => {
    const list = [];
    (t.sizes || LOGO_SIZES).forEach(([n,h]) => ["l","d"].forEach(bg => { if (bg === "d" && t.light === t.dark) return; list.push([n,h,bg]); }));
    for (const [n,h,bg] of list){ downloadLogo(t, bg, h, "svg", n); await new Promise(r => setTimeout(r, 180)); }
    toast(`Đã tải ${list.length} file SVG`);
  });
  upd(); openDrawer();
}
const slug = s => s.normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/đ/g,"d").replace(/Đ/g,"D").replace(/[^a-zA-Z0-9]+/g,"-").replace(/^-|-$/g,"").toLowerCase();
function saveBlob(blob, name){ const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(a.href), 4000); }
function downloadLogo(t, bg, h, fmt, sizeName){
  const key = bg === "d" ? t.dark : t.light, ratio = t.w / t.h;
  const svg = svgSized(key, h, ratio);
  const base = `fptshop-${t.k}-${t.light === t.dark ? '' : (bg === "d" ? "nen-toi-" : "nen-sang-")}${sizeName ? sizeName.toLowerCase()+'-' : ''}${h}px`.replace(/--/g,"-");
  if (fmt === "svg"){ saveBlob(new Blob([svg], {type:"image/svg+xml"}), base + ".svg"); if (!sizeName) toast("Đang tải " + base + ".svg"); return; }
  const scale = {png1:1, png2:2, png3:3}[fmt];
  const img = new Image();
  img.onload = () => {
    const c = document.createElement("canvas"); c.width = Math.round(h*ratio*scale); c.height = Math.round(h*scale);
    c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
    c.toBlob(b => { saveBlob(b, `${base}@${scale}x.png`); toast(`Đang tải ${base}@${scale}x.png`); }, "image/png");
  };
  img.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
}

