const linkCard = (x, href) => `<a class="card lcard" href="${href}" target="_blank" rel="noopener"><div class="gi">${I(x.i)}</div><div style="flex:1"><h3>${x.t}</h3><p>${x.d}</p></div><span class="go">${I("external")}</span></a>`;
