/* ---------- Supabase: đăng nhập + đồng bộ ---------- */
const DEMO_PROJECTS = PROJECTS.slice();
const BUILTIN_PDFS = PDFS.slice();
const DEMO_PEOPLE = PEOPLE.slice();
function requireAuth(what){
  if (!Cloud.on || Cloud.user) return true;
  openAuth(`Cần đăng nhập để ${what}. Dùng email và mật khẩu quản trị viên đã cấp.`);
  return false;
}
function renderAuth(){
  const slot = $("#auth-slot"); if (!slot) return;
  if (Cloud.on && $("#f-demo-note")) $("#f-demo-note").style.display = "none";
  if (!Cloud.on){ slot.innerHTML = `<div class="me" title="Chế độ demo: chưa kết nối Supabase">PH</div>`; return; }
  if (!Cloud.user){ slot.innerHTML = `<button class="auth-btn" id="auth-open">${I("link")}Đăng nhập</button>`; return; }
  const m = Cloud.member || {name: Cloud.user.email, color: "#212529"};
  slot.innerHTML = `<span class="cloud-dot">Đã đồng bộ</span> <button class="me" id="auth-open" title="${esc(m.name)}" style="background:${m.color};border-color:rgba(255,255,255,.6)">${initials(m.name)}</button>`;
  slot.style.display = "flex"; slot.style.alignItems = "center"; slot.style.gap = "10px";
}
function openAuth(why){
  lastFocus = document.activeElement;
  const logged = !!Cloud.user;
  $("#a-in").hidden = logged; $("#a-sent").hidden = true; $("#a-me").hidden = !logged;
  $("#amodal-title").textContent = logged ? "Tài khoản" : "Đăng nhập Design Hub";
  $("#a-why").textContent = why || "Đăng nhập bằng email và mật khẩu quản trị viên đã cấp.";
  if (logged){ $("#a-name").value = Cloud.member?.name || ""; $("#a-email-show").textContent = Cloud.user.email; }
  $("#amodal").classList.add("open"); $("#amodal").setAttribute("aria-hidden","false"); $("#scrim").classList.add("open");
  $("#fd-pass").classList.remove("err"); setTimeout(() => (logged ? $("#a-name") : $("#a-email")).focus(), 50);
}
document.addEventListener("click", e => { if (e.target.closest("#auth-open")) openAuth(); });
function authErr(m){
  if (/invalid login credentials/i.test(m)) return "Sai email hoặc mật khẩu.";
  if (/email not confirmed/i.test(m)) return "Tài khoản chưa được xác nhận. Nhờ quản trị viên bật Auto Confirm khi tạo tài khoản.";
  if (/rate limit/i.test(m)) return "Đã gửi quá nhiều email, thử lại sau khoảng 1 giờ (hoặc đăng nhập bằng mật khẩu).";
  if (/error sending/i.test(m)) return "Máy chủ email chưa gửi được. Hãy đăng nhập bằng mật khẩu.";
  if (/signups? not allowed|not found/i.test(m)) return "Email này chưa có tài khoản. Nhờ quản trị viên tạo tài khoản cho bạn.";
  if (/password should be|weak/i.test(m)) return "Mật khẩu quá yếu, cần tối thiểu 8 ký tự.";
  return m;
}
$("#aform").addEventListener("submit", async e => {
  e.preventDefault(); if (Cloud.user) return;
  const email = $("#a-email").value.trim(), pass = $("#a-pass").value;
  const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && pass.length > 0;
  $("#fd-pass").classList.toggle("err", !ok); $("#a-msg").textContent = "Nhập đủ email và mật khẩu"; if (!ok) return;
  const btn = $("#a-send"); btn.classList.add("busy");
  try { await Cloud.signInPassword(email, pass); $("#a-pass").value = ""; closeAll(); toast("Đã đăng nhập"); }
  catch(err){ $("#fd-pass").classList.add("err"); $("#a-msg").textContent = authErr(err.message); }
  finally { btn.classList.remove("busy"); }
});
$("#a-magic").addEventListener("click", async () => {
  const email = $("#a-email").value.trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){ $("#fd-pass").classList.add("err"); $("#a-msg").textContent = "Nhập email trước rồi bấm gửi link"; return; }
  const btn = $("#a-magic"); btn.classList.add("busy");
  try { await Cloud.signIn(email); $("#a-in").hidden = true; $("#a-sent").hidden = false; }
  catch(err){ $("#fd-pass").classList.add("err"); $("#a-msg").textContent = authErr(err.message); }
  finally { btn.classList.remove("busy"); }
});
$("#a-out").addEventListener("click", async () => { await Cloud.signOut(); closeAll(); toast("Đã đăng xuất"); });
$("#a-save").addEventListener("click", async () => {
  const n = $("#a-name").value.trim(), np = $("#a-newpass").value;
  $("#fd-newpass").classList.toggle("err", !!np && np.length < 8); if (np && np.length < 8) return;
  try {
    if (n && n !== Cloud.member?.name){ await Cloud.rename(n); await loadCloud(); renderAuth(); }
    if (np){ await Cloud.changePassword(np); $("#a-newpass").value = ""; }
    closeAll(); toast(np ? "Đã lưu và đổi mật khẩu" : "Đã lưu");
  } catch(err){ toast("Không lưu được: " + authErr(err.message)); }
});
async function toWebp(dataUrl, max){
  const img = await new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = dataUrl; });
  const s = Math.min(1, max / Math.max(img.width, img.height));
  const c = document.createElement("canvas"); c.width = Math.round(img.width*s); c.height = Math.round(img.height*s);
  c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
  return new Promise(r => c.toBlob(r, "image/webp", .85));
}
const hashNum = s => [...String(s)].reduce((a,c) => (a*31 + c.charCodeAt(0)) >>> 0, 7);
async function loadCloud(){
  let d;
  try { d = await Cloud.load(); } catch(err){ toast(err.message); return; }
  // Thành viên
  PEOPLE.splice(0, PEOPLE.length, ...(d.members.length ? d.members.map(m => ({id: m.id, name: m.name, color: m.color})) : DEMO_PEOPLE));
  // Font của team
  for (let i = FONTS.length - 1; i >= 0; i--) if (FONTS[i].src === "cloud") FONTS.splice(i, 1);
  const cloudFonts = d.fonts.filter(f => f.files.length).map(f => {
    const fam = "C_" + f.id.replace(/-/g, "");
    const single = f.files.length === 1;
    f.files.forEach(x => { KNOWN_HASH.add(x.sha1); const ff = new FontFace(fam, `url(${x.url})`, {weight: single ? "1 1000" : String(x.weight)}); document.fonts.add(ff); ff.load().catch(() => {}); });
    return { k: "c" + f.id, name: f.name, fam, cat: f.category, src: "cloud", role: (f.role || "Tải lên bởi " + f.by) + (f.vn_support === false ? " · thiếu dấu TV" : ""), weights: f.files.map(x => [x.weight, x.style || WN[x.weight] || "Regular"]), use: f.use_case || USE_BY_CAT[f.category] || "", lic: f.license || "check",
      files: f.files.map(x => ({label: x.style || WN[x.weight] || "Regular", href: x.url, name: x.file_name})) };
  });
  FONTS.unshift(...cloudFonts);
  // Guideline: bản trên cloud thay bản có sẵn cùng tên
  const cloudPdfs = d.guidelines.map(g => ({ id: "c" + g.id, title: g.title, cat: g.category, pages: g.pages, size: fmtSize(g.size_bytes || 0), date: (g.updated_at || "").slice(0,10), by: g.by, src: g.url, cover: g.cover, file: g.file_name }));
  const titles = new Set(cloudPdfs.map(p => p.title.toLowerCase()));
  PDFS = [...cloudPdfs, ...BUILTIN_PDFS.filter(p => !titles.has(p.title.toLowerCase()))];
  // Task: dữ liệu thật thay dữ liệu mẫu
  PROJECTS = d.projects.map(p => ({ title: p.title, sub: p.title.split(/[–-]/)[0].trim().slice(0, 28), type: p.type, people: p.people, date: p.done_at, tags: p.tags || [], link: p.link, thumb: p.thumb, art: hashNum(p.id) % ART.length, source: p.source }));
  const note = document.querySelector("#view-projects .page-head .note"); if (note) note.style.display = "none";
  $("#proj-empty").innerHTML = `<img src="${MASCOT_IMG.timkiem}" alt=""><b>${PROJECTS.length ? "Không tìm thấy task nào" : "Chưa có task nào"}</b><div>${PROJECTS.length ? "Thử bỏ bớt bộ lọc hoặc đổi từ khoá." : "Bấm “Thêm thủ công” để lưu task đầu tiên."}</div>`;
  renderFonts(); renderGuide(); renderFilters(); renderProjects(); counts();
  if (Cloud.member) $("#f-person").value = Cloud.member.id;
}

hydrateIcons(); renderFonts(); renderBrand(); renderDS(); renderGuide(); renderFilters(); renderProjects(); counts(); renderAuth();
if (Cloud.on){
  Cloud.init(() => { renderAuth(); loadCloud(); }).then(() => { renderAuth(); loadCloud(); }).catch(err => toast("Không kết nối được Supabase: " + err.message));
}

